import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        char first_char = s.charAt(0);
        s = s.substring(1);
        int pos_at = s.indexOf("at");
        if (pos_at != -1) {
            s = s.substring(0, pos_at) + "@" + s.substring(pos_at + 2);
        }
        int pos_dot;
        while ((pos_dot = s.indexOf("dot")) != -1 && pos_dot != s.length() - 3) {
            s = s.substring(0, pos_dot) + "." + s.substring(pos_dot + 3);
        }
        System.out.println(first_char + s);
        scanner.close();
    }
}
